+        backdrop-filter: blur(18px);
+      }
+
+      .eyebrow {
+        margin: 0 0 10px;
+        color: var(--accent);
+        font-size: 0.78rem;
+        font-weight: 700;
+        letter-spacing: 0.14em;
+        text-transform: uppercase;
+      }
+
+      h1 {
+        margin: 0;
+        font-size: clamp(2rem, 6vw, 3rem);
+        line-height: 1;
+      }
+
+      .intro {
+        margin: 16px 0 28px;
+        color: var(--muted);
+        line-height: 1.6;
+      }
+
+      form {
+        display: grid;
+        gap: 18px;
+      }
+
+      .form-field {
+        display: grid;
+        gap: 8px;
+      }
+
+      label {
+        color: #d1d5db;
+        font-size: 0.95rem;
+        font-weight: 650;
+      }
+
+      input {
+        width: 100%;
+        border: 1px solid var(--border);
+        border-radius: 14px;
+        background: var(--panel-strong);
+        color: var(--text);
+        font: inherit;
+        padding: 14px 16px;
+        outline: none;
+        transition:
+          border-color 160ms ease,
+          box-shadow 160ms ease,
+          background 160ms ease;
+      }
+
+      input::placeholder {
+        color: #6b7280;
+      }
+
+      input:focus {
+        border-color: var(--accent);
+        box-shadow: 0 0 0 4px var(--focus);
+        background: #111827;
+      }
+
+      .helper-text {
+        color: var(--muted);
+        font-size: 0.86rem;
+      }
+
+      button {
+        margin-top: 6px;
+        border: 0;
+        border-radius: 14px;
