 <!DOCTYPE html>
 <html lang="en">
   <head>
     <meta charset="UTF-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <title>Support Contact Form</title>
     <style>
       :root {
         color-scheme: dark;
         --bg: #0d1117;
         --panel: #161b22;
         --panel-strong: #1f2937;
         --text: #f0f6fc;
         --muted: #9ca3af;
         --accent: #58a6ff;
         --accent-strong: #1f6feb;
         --border: #30363d;
         --focus: rgba(88, 166, 255, 0.35);
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         min-height: 100vh;
         display: grid;
         place-items: center;
         padding: 32px 16px;
         background:
           radial-gradient(circle at top left, rgba(88, 166, 255, 0.18), transparent 32rem),
           linear-gradient(135deg, #05080d 0%, var(--bg) 48%, #111827 100%);
         color: var(--text);
         font-family:
           Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
           sans-serif;
       }

       .support-card {
         width: min(100%, 520px);
         padding: 34px;
         border: 1px solid var(--border);
         border-radius: 24px;
         background: rgba(22, 27, 34, 0.92);
         box-shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
         backdrop-filter: blur(18px);
       }

       .eyebrow {
         margin: 0 0 10px;
         color: var(--accent);
         font-size: 0.78rem;
         font-weight: 700;
         letter-spacing: 0.14em;
         text-transform: uppercase;
       }

       h1 {
         margin: 0;
         font-size: clamp(2rem, 6vw, 3rem);
         line-height: 1;
       }

       .intro {
         margin: 16px 0 28px;
         color: var(--muted);
         line-height: 1.6;
       }

       form {
         display: grid;
         gap: 18px;
       }

       .form-field {
         display: grid;
         gap: 8px;
       }

       label {
         color: #d1d5db;
         font-size: 0.95rem;
         font-weight: 650;
       }

       input {
         width: 100%;
         border: 1px solid var(--border);
         border-radius: 14px;
         background: var(--panel-strong);
         color: var(--text);
         font: inherit;
         padding: 14px 16px;
         outline: none;
         transition:
           border-color 160ms ease,
           box-shadow 160ms ease,
           background 160ms ease;
       }

       input::placeholder {
         color: #6b7280;
       }

       input:focus {
         border-color: var(--accent);
         box-shadow: 0 0 0 4px var(--focus);
         background: #111827;
       }

       .helper-text {
         color: var(--muted);
         font-size: 0.86rem;
       }

       button {
         margin-top: 6px;
         border: 0;
         border-radius: 14px;
         background: linear-gradient(135deg, var(--accent), var(--accent-strong));
         color: #ffffff;
         cursor: pointer;
         font: inherit;
         font-weight: 800;
         padding: 15px 18px;
         transition:
           transform 160ms ease,
           box-shadow 160ms ease,
           filter 160ms ease;
       }

       button:hover {
         box-shadow: 0 16px 36px rgba(31, 111, 235, 0.34);
         filter: brightness(1.06);
         transform: translateY(-1px);
       }

       button:active {
         transform: translateY(0);
       }
     </style>
   </head>
   <body>
     <main id="root"></main>

     <script>
       const createElement = (tag, props = {}, children = []) => {
         const element = document.createElement(tag);

         Object.entries(props).forEach(([key, value]) => {
           if (key === "className") {
             element.className = value;
           } else if (key === "textContent") {
             element.textContent = value;
           } else {
             element.setAttribute(key, value);
           }
         });

         children.forEach((child) => {
           element.append(child);
         });

         return element;
       };

       const Field = ({ id, label, type = "text", placeholder, required = false, helperText }) => {
         const input = createElement("input", {
           id,
           name: id,
           type,
           placeholder,
           autocomplete: id === "full-name" ? "name" : id,
           ...(required ? { required: "" } : {}),
         });

         const children = [
           createElement("label", { for: id, textContent: label }),
           input,
         ];

         if (helperText) {
           children.push(createElement("div", { className: "helper-text", textContent: helperText }));
         }

         return createElement("div", { className: "form-field" }, children);
       };

       const SupportContactForm = () => {
         const form = createElement("form", { action: "#", method: "post" }, [
           Field({
             id: "full-name",
             label: "Full name",
             placeholder: "Jane Doe",
             required: true,
           }),
           Field({
             id: "email",
             label: "Email address",
             type: "email",
             placeholder: "jane@example.com",
             required: true,
           }),
           Field({
             id: "tel",
             label: "Phone number",
             type: "tel",
             placeholder: "+1 (555) 123-4567",
             helperText: "Use international format when possible, e.g. +1 (555) 123-4567.",
           }),
           createElement("button", { type: "submit", textContent: "Contact support" }),
         ]);

         return createElement("section", { className: "support-card", "aria-labelledby": "support-title" }, [
           createElement("p", { className: "eyebrow", textContent: "Support" }),
           createElement("h1", { id: "support-title", textContent: "How can we help?" }),
           createElement("p", {
             className: "intro",
             textContent:
               "Send us your contact details and our support team will get back to you as soon as possible.",
           }),
           form,
         ]);
       };

       document.getElementById("root").append(SupportContactForm());
     </script>
   </body>
 </html>

